const MEALS = MEAL_RAW.map((r) => {
  const k = MEAL_KIND[r[5]] || MEAL_KIND.fresh;
  const split = (arr) => arr.flatMap((s) => String(s).split(/,\s*/).map((x) => x.trim()).filter(Boolean));
  const tr = (typeof MEAL_TR !== "undefined" && MEAL_TR[r[3]]) || {};
  const step = (i) => {
    const fx = STEP_FIX[r[3]];
    if (fx && fx[i]) return fx[i];
    return (k.s[i] || k.s[0])();
  };
  const gm = (i, main) => split((k.g[i] || k.g[0])(main, r[3]));
  return {
    cat: r[0], kcal: r[1], mins: r[2], kind: r[5], mac: macroFor(r[1], r[0], r[3]),
    name: r[3], desc: k.d[0], ing: gm(0, r[6]),
    steps: step(0),
    en: { name: r[4], desc: k.d[1], ing: gm(1, r[7]), steps: step(1) },
    ru: { name: (tr.ru && tr.ru[0]) || r[3], desc: k.d[2] || k.d[0], ing: gm(2, (tr.ru && tr.ru[1]) || r[6]), steps: step(2) },
    es: { name: (tr.es && tr.es[0]) || r[3], desc: k.d[3] || k.d[0], ing: gm(3, (tr.es && tr.es[1]) || r[6]), steps: step(3) },
    fr: { name: (tr.fr && tr.fr[0]) || r[3], desc: k.d[4] || k.d[0], ing: gm(4, (tr.fr && tr.fr[1]) || r[6]), steps: step(4) },
  };
});
/* Stabile Makro-Schätzung (Protein/KH/Fett in g) aus kcal + Kategorie.
   Deterministisch aus dem Namen gehasht — keine Laufzeit-Zufälle, keine Server. */
function macroFor(kcal, cat, name) {
  let h = 0;
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const jit = (n) => (((h >> (n * 5)) & 31) / 31) - 0.5;
  const pShare = cat === "protein" ? 0.38 : cat === "light" ? 0.28 : 0.14;
  const p = Math.max(2, Math.round((kcal * (pShare + jit(0) * 0.06)) / 4));
  const rest = kcal - p * 4;
  const cShare = cat === "energie" ? 0.62 : 0.5;
  const c = Math.max(2, Math.round((rest * (cShare + jit(1) * 0.1)) / 4));
  const f = Math.max(1, Math.round((rest - c * 4) / 9));
  return [p, c, f];
}
